            "find \"$1\" -type f -name \"$2\" | head -n 10",
            "_",        // $0 placeholder (script name)
            searchDir,  // $1
            filePattern // $2
        };

        Process process = null;
        try {
            // 3. Execute the command using Runtime.exec as required
            process = Runtime.getRuntime().exec(command);

            StringBuilder output = new StringBuilder();
            StringBuilder error = new StringBuilder();

            // 4. Read stdout and stderr streams
            // Sequential reading is safe here because 'head -n 10' strictly limits stdout volume,
            // preventing pipe buffer deadlocks.
            try (BufferedReader stdOut = new BufferedReader(new InputStreamReader(process.getInputStream()));
                 BufferedReader stdErr = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

                String line;
                while ((line = stdOut.readLine()) != null) {
                    output.append(line).append("\n");
                }
                while ((line = stdErr.readLine()) != null) {
                    error.append(line).append("\n");
                }
            }

            // 5. Wait for process completion and evaluate exit status
            int exitCode = process.waitFor();

            // Exit code 141 (SIGPIPE) is expected when 'head' closes the stream after 10 lines.
            // Any other non-zero exit code indicates a genuine failure.
            if (exitCode != 0 && exitCode != 141) {
                String errMsg = error.toString().trim();
                return "Search failed: " + (errMsg.isEmpty() ? "Command exited with code " + exitCode : errMsg);
            }

            // Return successfully found files, trimmed of trailing whitespace/newlines
            return output.toString().trim();

        } catch (IOException e) {
            return "Search failed: IO exception - " + e.getMessage();
        } catch (InterruptedException e) {
            // Restore the interrupted status of the current thread
            Thread.currentThread().interrupt();
            return "Search failed: Process interrupted - " + e.getMessage();
        } finally {
            // 6. Ensure system resources are released
            if (process != null && process.isAlive()) {
                process.destroy();
            }
        }
    }
}
